'use strict';
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const contentText=v=>`<span data-no-i18n>${esc(v)}</span>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const typeNames={short_answer:'觀念問答',formula_puzzle:'公式拼圖',ordering:'流程排序',matching:'概念配對',python:'Python 實作',calculation:'計算與推理',selection:'判斷與選擇',grid:'遮罩操作',case_proposal:'案例與改善方案',ai_collab_canvas:'AI 協作白板（測試）'};
const state={session:null,page:'dashboard',data:{},selected:[],task:null,index:0,saveTimer:null,savePromise:Promise.resolve(),runner:null,navigation:0};
const modal=$('#modal');
const label=v=>({'draft':'待覆核','approved':'已核准','rejected':'已退回','published':'已分配','assessment':'正式檢測','practice':'練習','in_progress':'作答中','submitted':'已繳交','analyzed':'已分析','queued':'等待分析','running':'AI 批改中','draft_ready':'分析完成','completed':'AI 已回應','failed':'分析失敗'}[v]||v);
const badge=(v,text)=>`<span class="badge ${['approved','draft_ready','analyzed'].includes(v)?'good':['draft','queued','running','submitted'].includes(v)?'warn':['failed','rejected'].includes(v)?'bad':''}">${esc(text||label(v))}</span>`;
const fmt=v=>v?i18n.date(v):'未設定';
function toast(text,tone){retroAudio.play(tone==='silent'?'silent':tone||(/^(已|來源已保存|設定已|密碼已|評量已|模型.*已)/.test(text)?'success':'notice'));const t=$('#toast');t.textContent=text;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',4000);}
async function api(path,data){const navigation=state.navigation;const options={credentials:'same-origin',headers:{}};if(data!==undefined){options.method='POST';options.headers={'Content-Type':'application/json','X-CSRF-Token':state.session?.csrf||''};options.body=JSON.stringify(data);}const r=await fetch(path,options);const body=await r.json();if(data===undefined&&path!='/api/session'&&navigation!==state.navigation){const stale=Error('頁面已切換');stale.name='AbortError';throw stale;}if(!r.ok){if(r.status===401&&path!='/api/login'){state.session=null;await boot();}throw Error(body.error||`請求失敗 (${r.status})`);}return body;}
function bind(selector,event,fn){const el=$(selector);if(el)el.addEventListener(event,fn);}
function busy(button,fn){return async e=>{e.preventDefault();button.disabled=true;try{await fn(e);}catch(x){toast(x.message,'error');}finally{button.disabled=false;}};}
const field=(name,title,control,help='')=>`<div class="field"><label for="${name}">${title}</label>${control}${help?`<small>${help}</small>`:''}</div>`;
const input=(id,type='text',value='',extra='')=>`<input id="${id}" type="${type}" value="${esc(value)}" ${extra}>`;
function openModal(title,html,actions=''){modal.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="quiet" id="close-modal" aria-label="關閉">✕</button></div>${html}${actions?`<div class="modal-actions">${actions}</div>`:''}`;modal.showModal();retroAudio.play('dialog');bind('#close-modal','click',()=>modal.close());}
function meters(){ $$('[data-percent]').forEach(e=>e.style.width=`${Math.max(0,Math.min(100,Number(e.dataset.percent)))}%`);$$('[data-height]').forEach(e=>e.style.height=`${Number(e.dataset.height)}px`);}
function head(eyebrow,title,description,actions=''){return `<div class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1 ${state.task||eyebrow==='REVIEW WORKSPACE'||(eyebrow==='MY FEEDBACK'&&title!=='理解的證據，下一步的方向。')?'data-no-i18n':''}>${esc(title)}</h1><p>${esc(description)}</p></div><div class="buttons">${actions}</div></div>`;}

async function boot(){try{state.session=await api('/api/session');await i18n.syncUser(state.session.user);await retroAudio.syncUser(state.session.user);if(!state.session.user)return login();state.page=state.session.user.role==='admin'?'dashboard':'tasks';await navigate(state.page);}catch(e){$('#app').innerHTML=`<div class="loading">${esc(e.message)}</div>`;}}
function login(){const setup=state.session.setup_required;$('#app').innerHTML=`<main class="login"><section class="login-story"><div class="brand"><img src="/favicon.svg" alt=""><div>知序<small>LLM ASSESSMENT STUDIO</small></div></div><div><div class="eyebrow">FROM UNDERSTANDING TO ACTION</div><h1>看懂原理。<br>讀懂案例。<br><em>提出下一步。</em></h1><p>從語言模型基礎到架構選擇，以作答證據檢視理解，再把想法轉化為可驗證的改善方案。</p><div class="login-tags"><span>概念問答</span><span>互動拼圖</span><span>程式實作</span></div></div><footer>ZJU-LLMs CHAPTER 01—02 · INDEPENDENT WORKSPACE</footer></section><section class="login-form"><form class="login-box" id="login-form"><div class="eyebrow">${setup?'INITIAL SETUP':'WELCOME BACK'}</div><h2>${setup?'建立管理者帳戶':'登入你的工作區'}</h2><p>${setup?'先在這台主機設定帳戶，再邀請組員加入。':'使用管理者提供的帳號，繼續你的評量。'}</p>${setup?field('name','管理者姓名',input('name','text','', 'required autocomplete="name"')):''}${field('email','帳號',input('email','text','', 'required autocomplete="username"'))}${field('password','密碼',input('password','password','',`required minlength="10" autocomplete="${setup?'new-password':'current-password'}"`),setup?'至少 10 個字元。':'')}<div class="form-error" id="login-error"></div><button class="btn primary" type="submit">${setup?'建立工作區':'登入工作區'} <span>→</span></button><p class="tiny muted">帳戶及評量資料儲存於主機後端。</p></form></section></main>`;bind('#login-form','submit',async e=>{e.preventDefault();const btn=$('#login-form button');btn.disabled=true;try{const values={email:$('#email').value,password:$('#password').value};if(setup){await api('/api/setup',{...values,name:$('#name').value});}await api('/api/login',values);await boot();}catch(x){$('#login-error').textContent=x.message;retroAudio.play('error');}finally{btn.disabled=false;}});}
function shell(content){const u=state.session.user,admin=u.role==='admin';const nav=admin?[['dashboard','◈','工作區總覽'],['questions','▦','題庫與覆核'],['examstudio','▣','教材出題工作室'],['modelslots','▧','模型轉接槽'],['assignments','▤','組卷與分配'],['learners','◎','組員管理'],['submissions','◷','作答與批改'],['overview','↗','能力與支持'],['settings','⚙','系統設定']]:[['tasks','▤','我的評量'],['reports','↗','我的報告'],['settings','⚙','帳戶設定']];$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><img src="/favicon.svg" alt=""><div>知序<small>ASSESSMENT STUDIO</small></div></div><div class="nav-heading">${admin?'MANAGEMENT':'MY WORKSPACE'}</div><nav class="nav">${nav.map(([id,icon,text])=>`<button data-nav="${id}" class="${state.page===id?'active':''}"><span class="nav-icon">${icon}</span>${text}</button>`).join('')}</nav><div class="side-footer"><div class="profile"><span class="avatar">${esc(u.display_name[0])}</span><div><div class="tiny">${esc(u.display_name)}</div><small>${admin?'管理者':'組員'}</small></div></div><button class="quiet" id="logout">登出工作區 →</button></div></aside><main class="main"><div class="topbar"><span>WORKSPACE / ${admin?'管理者':'組員'}</span><span class="pill"><span class="status-dot"></span>CH 01 · CH 02</span><button class="quiet mobile-menu" id="mobile-logout">登出</button></div><div id="content">${content}</div></main></div>`;$$('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));bind('#logout','click',logout);bind('#mobile-logout','click',logout);meters();}
async function logout(){try{if(state.task)await saveCurrent();await api('/api/logout',{});state.task=null;state.session=null;await boot();}catch(e){toast(e.message);}}
async function navigate(page){const navigation=++state.navigation;try{if(state.task){await saveCurrent();if(navigation!==state.navigation)return;state.task=null;}state.page=page;shell('<div class="loading">正在載入工作區…</div>');const routes={examstudio:examStudio,modelslots:modelSlots,dashboard:dashboard,questions:questions,assignments:assignments,learners:learners,submissions:submissions,overview:overview,tasks:tasks,reports:reports,settings:settings};await routes[page]();}catch(e){if(e.name==='AbortError'||navigation!==state.navigation)return;const target=$('#content');if(target)target.innerHTML=`<div class="note bad">${esc(e.message)}</div>`;}}
function content(html){$('#content').innerHTML=html;meters();}
async function dashboard(){const d=await api('/api/admin/dashboard');content(head('YOUR ASSESSMENT WORKSPACE','理解，才是起點。','把題目、作答與下一步改善放在同一條可追溯的評量流程。','<button class="btn primary" id="new-assignment">＋ 建立評量</button>')+`<section class="hero"><div><div class="eyebrow">EVIDENCE → INSIGHT → NEXT STEP</div><h2>從「會回答」<br>走到「知道怎麼改善」。</h2><p>概念與實作一起檢測，AI 按規準提出分數與證據；你可以進一步檢視、調整與發布。</p></div><div class="hero-art" aria-hidden="true">${'<i></i>'.repeat(9)}</div></section><div class="stats">${[['題庫題目',d.counts.questions,'涵蓋概念、互動與實作'],['已核准版本',d.counts.approved,'可加入正式評量'],['組員',d.counts.learners,'獨立帳戶與作答紀錄'],['已繳交',d.counts.submissions,`${d.counts.pending} 份等待或正在分析`]].map(([t,n,s])=>`<div class="stat"><label>${t}</label><strong>${n}</strong><small>${s}</small></div>`).join('')}</div><div class="columns"><section class="panel"><div class="panel-head"><h2>最近的分析</h2><button class="quiet" id="to-submissions">查看全部 →</button></div>${d.jobs.length?`<div class="table-wrap"><table><thead><tr><th>評量 / 組員</th><th>狀態</th><th>建立時間</th></tr></thead><tbody>${d.jobs.map(j=>`<tr><td><strong>${esc(j.title)}</strong><br><small>${esc(j.display_name)}</small></td><td>${badge(j.status)}</td><td class="tiny muted">${fmt(j.created_at*1000)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">尚無作答分析。<br>核准題目並分配評量後，繳交內容會出現在這裡。</div>'}</section><section class="panel"><div class="panel-head"><h2>準備你的第一次評量</h2></div><div class="list-row"><div><h3>01 · 題目覆核</h3><p>查看來源、答案與分項規準。</p></div><button class="btn small" id="to-bank">查看</button></div><div class="list-row"><div><h3>02 · 建立組員</h3><p>提供每人獨立登入帳戶。</p></div><button class="btn small" id="to-learners">新增</button></div><div class="list-row"><div><h3>03 · 啟用批改</h3><p>AI ${d.model_ready&&d.ai.enabled?'可用':'指定模型尚未就緒'}（${esc(d.ai.model)}） · 隔離測試 ${d.runner.available?'可用':'尚未就緒'}</p></div><button class="btn small" id="to-settings">設定</button></div></section></div>`);bind('#new-assignment','click',()=>navigate('assignments'));bind('#to-submissions','click',()=>navigate('submissions'));bind('#to-bank','click',()=>navigate('questions'));bind('#to-learners','click',()=>navigate('learners'));bind('#to-settings','click',()=>navigate('settings'));}

async function questions(){state.data.bank=await api('/api/admin/questions');const bank=state.data.bank;content(head('QUESTION LIBRARY','讓每道題，都有檢測目的。',`${bank.questions.length} 題 · 題幹、答案、規準與版本統一管理。`,'<button class="btn" id="export-bank">匯出題庫</button><button class="btn" id="import-bank">匯入</button><button class="btn primary" id="add-question">＋ 新增題目</button>')+`<section class="panel"><div class="filters">${input('search-question','search','', 'placeholder="搜尋題名、題號或小節…" aria-label="搜尋題目"')}<select id="filter-section" aria-label="小節"><option value="">全部小節</option>${bank.skills.map(s=>`<option>${esc(s.id)}</option>`).join('')}</select><select id="filter-kind" aria-label="題型"><option value="">全部題型</option>${Object.entries(typeNames).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><select id="filter-language" aria-label="題目語言"><option value="">全部語言</option><option value="en">English</option><option value="zh-TW">中文</option></select><select id="filter-status" aria-label="狀態"><option value="">全部狀態</option>${['draft','approved','rejected'].map(s=>`<option value="${s}">${label(s)}</option>`).join('')}</select></div><div class="panel-head"><small id="bank-count"></small><button class="btn small" id="approve-selected">核准勾選題目</button></div><div class="table-wrap"><table><thead><tr><th><input type="checkbox" id="select-all-questions" aria-label="勾選全部可見题目"></th><th>題目</th><th>題型</th><th>版本</th><th>狀態</th><th></th></tr></thead><tbody id="question-rows"></tbody></table></div></section><input class="upload" id="bank-upload" type="file" accept="application/json">`);function rows(){const term=$('#search-question').value.toLowerCase(),sec=$('#filter-section').value,kind=$('#filter-kind').value,status=$('#filter-status').value,language=$('#filter-language').value;const list=bank.questions.filter(q=>(q.question_id+' '+q.title+' '+q.skill_id+' '+q.prompt).toLowerCase().includes(term)&&(!sec||q.skill_id===sec)&&(!kind||q.kind===kind)&&(!status||q.review_status===status)&&(!language||(q.payload.language||'zh-TW')===language));$('#bank-count').textContent=`顯示 ${list.length} 題`;$('#question-rows').innerHTML=list.map(q=>`<tr><td><input type="checkbox" data-question-check="${esc(q.id)}" aria-label="選擇 ${esc(q.title)}"></td><td><span class="section-number">${esc(q.skill_id)}</span>${badge('',q.payload.language==='en'?'EN':'中文')}<span class="question-title">${esc(q.title)}</span><br><small>${esc(q.question_id)}</small></td><td>${typeNames[q.kind]}</td><td class="mono">v${q.version}</td><td>${badge(q.review_status)}</td><td><button class="btn small" data-review-question="${esc(q.id)}">查看 / 覆核</button></td></tr>`).join('');$$('[data-review-question]').forEach(b=>b.onclick=()=>questionModal(bank.questions.find(q=>q.id===b.dataset.reviewQuestion)));}rows();['#search-question','#filter-section','#filter-kind','#filter-status','#filter-language'].forEach(s=>bind(s,'input',rows));bind('#select-all-questions','change',e=>$$('[data-question-check]').forEach(x=>x.checked=e.target.checked));bind('#approve-selected','click',busy($('#approve-selected'),async()=>{const ids=$$('[data-question-check]:checked').map(x=>x.dataset.questionCheck);if(!ids.length)throw Error('請先勾選題目');for(const id of ids)await api(`/api/admin/questions/${id}/approve`,{});toast(`已核准 ${ids.length} 題`);await questions();}));bind('#add-question','click',()=>editQuestion({...bank.questions[0],title:'新題目',prompt:'請輸入完整題幹。'},true));bind('#export-bank','click',async()=>{try{const pack=await api('/api/admin/export');download('llm-assessment-bank.json',JSON.stringify(pack,null,2));}catch(e){toast(e.message);}});bind('#import-bank','click',()=>$('#bank-upload').click());bind('#bank-upload','change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1500000)throw Error('匯入檔過大');const result=await api('/api/admin/import',JSON.parse(await file.text()));toast(`已匯入 ${result.count} 題待覆核草稿`);await questions();}catch(x){toast(x.message,'error');}});}
function questionModal(q){const source=state.data.bank.sources.find(s=>s.id===q.source_id);openModal(q.title,`<div class="buttons">${badge(q.review_status)}${badge('',typeNames[q.kind])}<span class="section-number">${esc(q.skill_id)}</span><small>v${q.version}</small></div><p class="prompt">${esc(q.prompt)}</p>${readingCodeMarkup(q)}${['selection','ordering','matching','grid','formula_puzzle'].includes(q.kind)?`<h3>選項與互動預覽</h3><fieldset disabled>${interaction(q,{})}</fieldset>`:''}<h3>參考答案與可接受要點</h3><ul class="rubric-list">${q.answer.expected_elements.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${guideMarkup(q)}<h3>分項評分規準 · ${q.rubric.total_points} 分</h3><div class="rubric-list">${q.rubric.criteria.map(r=>`<strong>${esc(r.name)} · ${r.points.toFixed(1)} 分</strong>${Object.entries(r.levels).map(([k,v])=>`<div>${k} 級：${esc(v)}</div>`).join('')}`).join('')}</div>${q.kind==='python'?`<h3>實作測試</h3><pre>${esc(JSON.stringify(q.tests,null,2))}</pre>`:''}<div class="note">來源：${esc(q.source_locator)}<br>${source?esc(source.path):''}<br><a href="/api/admin/source?id=${encodeURIComponent(q.source_id)}" target="_blank" rel="noopener">檢視後端來源快照 ↗</a></div>`,`<button class="btn" id="edit-question">建立修改版本</button><button class="btn danger" id="reject-question">退回</button><button class="btn primary" id="approve-question">核准此版本</button>`);bind('#edit-question','click',()=>editQuestion(q));bind('#reference-run','click',busy($('#reference-run'),async()=>{const r=await api(`/api/admin/questions/${q.id}/reference-run`,{});const out=$('#reference-run-output');out.hidden=false;out.textContent=r.status==='completed'?`通過 ${r.passed} / ${r.total} 個公開與隱藏測試`:r.error;}));['approve','reject'].forEach(action=>bind(`#${action}-question`,'click',busy($(`#${action}-question`),async()=>{await api(`/api/admin/questions/${q.id}/${action}`,{});modal.close();toast(action==='approve'?'題目已核准':'題目已退回');await questions();})));}
function editQuestion(q,isNew=false){openModal(isNew?'新增題目草稿':'建立新的題目版本',`<p class="note">修改會建立待覆核版本，已分配的評量保留原始快照。可編輯題幹、互動設定、答案、分項規準與測試。</p><div class="field"><label for="question-json">完整題目設定（JSON）</label><textarea class="json-editor" id="question-json" spellcheck="false">${esc(JSON.stringify(q,null,2))}</textarea></div>`,`<button class="btn primary" id="save-question">儲存待覆核草稿</button>`);bind('#save-question','click',busy($('#save-question'),async()=>{const value=JSON.parse($('#question-json').value);await api(isNew?'/api/admin/questions':`/api/admin/questions/${q.id}/version`,value);modal.close();toast('已儲存草稿');await questions();}));}

async function learners(){const d=await api('/api/admin/learners');content(head('TEAM MEMBERS','每個人，一份理解軌跡。','建立獨立帳戶，保留個人的作答、分數與回饋。','<button class="btn primary" id="add-learner">＋ 新增組員</button>')+`<section class="panel">${d.learners.length?`<table><thead><tr><th>組員</th><th>登入帳號</th><th>狀態</th><th></th></tr></thead><tbody>${d.learners.map(l=>`<tr><td><strong data-no-i18n>${esc(l.display_name)}</strong></td><td>${esc(l.email)}</td><td>${badge(l.disabled?'rejected':'approved',l.disabled?'已停用':'可登入')}</td><td><button class="btn small" data-reset="${l.id}">重設密碼</button> <button class="quiet" data-disable="${l.id}" data-disabled="${l.disabled}">${l.disabled?'啟用':'停用'}</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">尚未建立組員。新增後即可進行分配。</div>'}</section>`);bind('#add-learner','click',()=>{openModal('新增組員',field('member-name','姓名',input('member-name'))+field('member-email','登入帳號',input('member-email'))+field('member-password','初始密碼',input('member-password','password','','minlength="10" autocomplete="new-password"'),'至少 10 字元，組員登入後可自行更改。'),'<button class="btn primary" id="save-learner">建立帳戶</button>');bind('#save-learner','click',busy($('#save-learner'),async()=>{await api('/api/admin/learners',{name:$('#member-name').value,email:$('#member-email').value,password:$('#member-password').value});modal.close();toast('組員帳戶已建立');await learners();}));});$$('[data-reset]').forEach(b=>b.onclick=()=>{openModal('重設組員密碼',field('reset-password','新密碼',input('reset-password','password','','minlength="10" autocomplete="new-password"')),'<button class="btn primary" id="confirm-reset">更新密碼並登出舊工作階段</button>');bind('#confirm-reset','click',busy($('#confirm-reset'),async()=>{await api(`/api/admin/learners/${b.dataset.reset}/reset`,{password:$('#reset-password').value});modal.close();toast('密碼已更新');}));});$$('[data-disable]').forEach(b=>b.onclick=async()=>{try{await api(`/api/admin/learners/${b.dataset.disable}/disable`,{disabled:b.dataset.disabled==='0'});await learners();}catch(e){toast(e.message);}});}

async function assignments(){const [bank,members,existing]=await Promise.all([api('/api/admin/questions'),api('/api/admin/learners'),api('/api/admin/assignments')]);state.data.bank=bank;state.data.members=members;state.selected=[];const approved=bank.questions.filter(q=>q.review_status==='approved');content(head('COMPOSE & ASSIGN','搭配題目，安排檢測。','你決定內容、配分、對象，以及 AI 分數何時發布。')+`<div class="columns"><section class="panel"><div class="panel-head"><h2>01 · 選擇已核准題目</h2><small>${approved.length} 題可選</small></div>${input('compose-search','search','','placeholder="搜尋題名、題號或小節…" aria-label="搜尋可選題目"')}<div id="compose-questions" class="question-list"></div></section><section class="panel"><h2>02 · 評量設定</h2><div class="field"><label for="assignment-title">評量名稱</label>${input('assignment-title','text','','placeholder="例如：CH1 基礎理解與實作"')}</div><div class="form-grid">${field('assignment-mode','模式','<select id="assignment-mode"><option value="assessment">正式檢測</option><option value="practice">練習</option></select>')}${field('assignment-due','期限（台北時間）',input('assignment-due','datetime-local'))}</div><h3>選題順序與配分</h3><div id="selected-questions" class="stack"></div><p class="tiny muted" id="total-points"></p><div class="answer-label">分配組員</div>${members.learners.filter(l=>!l.disabled).map(l=>`<label class="check-label"><input type="checkbox" data-recipient="${l.id}">${esc(l.display_name)} <small>${esc(l.email)}</small></label>`).join('')||'<p class="tiny muted">請先到組員管理建立帳戶。</p>'}<div class="answer-label">批改與支援條件</div><label class="check-label"><input type="checkbox" id="auto-publish" checked>AI 完整批改後自動發布分數</label><label class="check-label"><input type="checkbox" id="publish-code">實作題也允許自動發布（仍可人工調分）</label><label class="check-label"><input type="checkbox" id="allow-practice">開放公開測試試跑</label><label class="check-label"><input type="checkbox" id="allow-browser" checked>開放瀏覽器 Python 練習</label>${field('support-note','其他支援条件',input('support-note','text','','placeholder="查教材、使用 AI 等規定"'))}<button class="btn primary" id="publish-assignment">建立並分配評量 →</button></section></div><section class="panel"><div class="panel-head"><h2>已建立的評量</h2></div>${existing.assignments.length?`<table><thead><tr><th>評量</th><th>模式</th><th>题目 / 組員</th><th>期限</th></tr></thead><tbody>${existing.assignments.map(a=>`<tr><td><strong>${esc(a.title)}</strong><br><small>${fmt(a.created_at)}</small></td><td>${badge(a.mode)}</td><td>${a.item_count} 題 / ${a.recipient_count} 人</td><td>${fmt(a.due_at)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">建立的評量會顯示在這裡。</div>'}</section>`);function choices(){const term=$('#compose-search').value.toLowerCase();$('#compose-questions').innerHTML=approved.filter(q=>(q.title+' '+q.skill_id).toLowerCase().includes(term)).map(q=>`<label class="select-question"><input type="checkbox" data-compose="${q.id}" ${state.selected.some(x=>x.id===q.id)?'checked':''}><span><b>${esc(q.title)}</b><small><span class="section-number">${q.skill_id}</span>${typeNames[q.kind]} · v${q.version}</small></span><small>12 分</small></label>`).join('')||'<div class="empty">沒有可選題目。請先覆核並核准題庫內容。</div>';$$('[data-compose]').forEach(x=>x.onchange=()=>{if(x.checked)state.selected.push({id:x.dataset.compose,points:12});else state.selected=state.selected.filter(s=>s.id!==x.dataset.compose);selection();});}function selection(){$('#selected-questions').innerHTML=state.selected.map((s,i)=>`<div class="selected-row"><span class="tiny">${i+1}. ${esc(approved.find(q=>q.id===s.id).title)}</span><input type="number" data-points="${s.id}" value="${s.points}" min="1" max="1000" aria-label="題目配分"><span><button class="quiet" data-up="${i}" aria-label="向前移動">↑</button><button class="quiet" data-remove="${s.id}" aria-label="移除題目">×</button></span></div>`).join('')||'<div class="empty">從左側選題。</div>';$('#total-points').textContent=`${state.selected.length} 題 · 總分 ${state.selected.reduce((a,b)=>a+Number(b.points),0)}`;$$('[data-points]').forEach(x=>x.oninput=()=>{state.selected.find(s=>s.id===x.dataset.points).points=Number(x.value);$('#total-points').textContent=`${state.selected.length} 題 · 總分 ${state.selected.reduce((a,b)=>a+b.points,0)}`;});$$('[data-up]').forEach(x=>x.onclick=()=>{const i=Number(x.dataset.up);if(i>0)[state.selected[i-1],state.selected[i]]=[state.selected[i],state.selected[i-1]];selection();});$$('[data-remove]').forEach(x=>x.onclick=()=>{state.selected=state.selected.filter(s=>s.id!==x.dataset.remove);choices();selection();});}choices();selection();bind('#compose-search','input',choices);bind('#assignment-mode','change',()=>$('#allow-practice').checked=$('#assignment-mode').value==='practice');bind('#publish-assignment','click',busy($('#publish-assignment'),async()=>{const due=$('#assignment-due').value;const result=await api('/api/admin/assignments',{title:$('#assignment-title').value,mode:$('#assignment-mode').value,items:state.selected,recipients:$$('[data-recipient]:checked').map(x=>x.dataset.recipient),due_at:due?new Date(due+'+08:00').toISOString():null,auto_publish:$('#auto-publish').checked,publish_code_ai:$('#publish-code').checked,allow_practice:$('#allow-practice').checked,allow_browser:$('#allow-browser').checked,support_note:$('#support-note').value});toast('評量已分配，組員可登入作答');await assignments();}));}

async function tasks(){const d=await api('/api/tasks');content(head('MY ASSESSMENTS','把理解，寫成證據。','完成已分配的問答、互動與實作，讓下一步改善有根據。')+`<section class="hero"><div><div class="eyebrow">UNDERSTAND · REASON · BUILD</div><h2>不只回答「是什麼」，<br>也試著解釋「為什麼」。</h2><p>閱讀案例時，記下條件與限制；提出改善時，說明如何驗證。</p></div><div class="hero-art" aria-hidden="true">${'<i></i>'.repeat(9)}</div></section>${d.tasks.length?d.tasks.map(a=>`<article class="task-card"><div><div class="buttons">${badge(a.mode)}${badge(a.submission_status||'draft',a.submission_status?undefined:'尚未開始')}</div><h3>${esc(a.title)}</h3><p>期限：${fmt(a.due_at)}</p></div><button class="btn ${!a.submission_status||a.submission_status==='in_progress'?'primary':''}" data-task="${a.id}">${a.submission_status&&a.submission_status!=='in_progress'?'查看作答':'開始 / 繼續作答'} →</button></article>`).join(''):'<div class="panel"><div class="empty">尚無已分配的評量。管理者分配後會顯示在這裡。</div></div>'}`);$$('[data-task]').forEach(b=>b.onclick=()=>openTask(b.dataset.task));}
async function openTask(id){try{state.task=await api(`/api/tasks/${id}/start`,{});state.index=0;renderTask();}catch(e){toast(e.message);}}
const cardLabels={'C(A)':'C(A)','C(A,B)':'C(A,B)','/':'÷',input:'取得當前輸入 xₜ',state_update:'結合上一狀態，更新 hₜ',output_distribution:'計算輸出機率分布',save_state:'保存 hₜ 供下一步',qk:'Q × Kᵀ',scale:'除以 √dₖ',mask:'套用注意力遮罩',softmax:'沿 key 維做 Softmax',value:'乘上 V',source_tokens:'來源句子 tokens',encoder_states:'Encoder 表示',decoder_prefix_and_cross_attention:'Decoder 前綴與 Cross-attention',next_target:'下一個目標 token',teacher_forcing:'Teacher forcing',generation:'自由生成',ground_truth_previous:'前一步真實 token',generated_previous:'前一步產生的 token',bert_self:'BERT 自注意力',causal_self:'自回歸 Decoder 自注意力',cross:'Cross-attention',bidirectional_input:'輸入的雙向上下文',prefix:'生成前綴（含當前位置）',encoder_memory:'Decoder 讀取 Encoder 表示',decoder:'Decoder 中間表示',encoder:'Encoder 輸出',input_dependent_selection:'輸入相依的狀態選擇',test_time_learning:'測試時學習更新內部記憶'};
const cardText=x=>cardLabels[x]||x;
const proposalLabels={observation:'結果與案例條件',problem_and_alternatives:'問題、原因假設與替代解釋',improvement_and_mechanism:'下一步改善與作用機制',validation_baseline_controls_metrics:'驗證方法：基準、控制變因與指標',constraints_and_failure:'資源取捨與失敗判準'};
function interaction(q,r){const p=q.payload,i=r.interaction||{},text=x=>p.labels?.[x]||cardText(x);let html='';if(q.kind==='ordering'||q.kind==='formula_puzzle'){const order=i.order||[...p.cards].reverse();html=`<div class="answer-label">拖曳卡片，或使用上下按鈕調整順序</div><div id="order-cards">${order.map(x=>`<div class="order-card" draggable="true" data-card="${esc(x)}"><span class="handle">⠿</span><span class="card-text">${esc(text(x))}</span><button class="quiet order-up" aria-label="上移">↑</button><button class="quiet order-down" aria-label="下移">↓</button></div>`).join('')}</div>`;if(q.kind==='formula_puzzle')html+=field('formula-result','計算結果',input('formula-result','text',i.result||''));}else if(q.kind==='matching'){html=`<div class="answer-label">建立對應關係</div>${p.left.map(left=>`<div class="match-row"><span>${esc(text(left))}</span><select data-match="${esc(left)}" aria-label="${esc(text(left))} 的對應"><option value="">請選擇</option>${p.right.map(right=>`<option value="${esc(right)}" ${i.mapping?.[left]===right?'selected':''}>${esc(text(right))}</option>`).join('')}</select></div>`).join('')}`;}else if(q.kind==='grid'){const grid=i.grid||Array.from({length:p.rows},()=>Array(p.columns).fill(0));html=`<div class="answer-label">列 = Query · 欄 = Key · 點選切換 0 / 1</div><div class="mask-grid"><span></span>${[1,2,3].map(v=>`<span>K${v}</span>`).join('')}${grid.map((row,a)=>`<span>Q${a+1}</span>${row.map((v,b)=>`<button class="${v?'on':''}" data-cell="${a},${b}" aria-label="Query ${a+1} Key ${b+1}" aria-pressed="${!!v}">${v}</button>`).join('')}`).join('')}</div>`;}else if(q.kind==='selection'&&p.options){html=`<div class="answer-label">${p.multiple?'複選：選出所有符合條件的選項':'單選：選出最符合條件的選項'}</div><div class="token-choices selection-options">${p.options.map(o=>`<label><input type="${p.multiple?'checkbox':'radio'}" ${p.multiple?'data-choice':'name="concept-choice"'} value="${esc(o.id)}" ${(p.multiple?i.choices?.includes(o.id):i.choice===o.id)?'checked':''}><span><b>${esc(o.id)}.</b> ${esc(o.label)}</span></label>`).join('')}</div>`;}else if(q.kind==='selection'&&p.candidates){html=`<div class="answer-label">選擇候選集合</div>${[['top_k','Top-k（k = 2）'],['top_p','Top-p（p = 0.80）']].map(([key,label])=>`<h3>${label}</h3><div class="token-choices">${Object.entries(p.candidates).map(([name,prob])=>`<label><input type="checkbox" data-token="${key}" value="${name}" ${i[key]?.includes(name)?'checked':''}>${name} <small>${prob.toFixed(2)}</small></label>`).join('')}</div>`).join('')}`;}else if(q.kind==='selection'){html=`<div class="token-choices"><label><input type="radio" name="concept-choice" value="true" ${i.choice==='true'?'checked':''}>正確</label><label><input type="radio" name="concept-choice" value="false" ${i.choice==='false'?'checked':''}>錯誤</label></div>`;}return html;}
function readingCodeMarkup(q){const code=q.payload?.reading_code;if(!code)return '';return `<section class="reading-code"><h3>${q.payload.language==='en'?'Read the code (no execution required)':'閱讀程式碼（不需執行）'}</h3><pre><code>${esc(code)}</code></pre></section>`;}
function starter(q){const fn=q.tests?.function;if(!fn)return'';const signatures={bigram_counts:'sentences',weighted_value:'weights, values',nucleus_indices:'probs, p',perplexity:'probs',next_token_pairs:'tokens',compare_predictions:'predictions, targets'};return `def ${fn}(${signatures[fn]||'*args'}):\n    # ${q.payload.language==='en'?'Complete the implementation here':'在這裡完成實作'}\n    raise NotImplementedError\n`;}
function caseReference(q){const data=q.payload.reference_data;if(!data)return'';const values=Object.entries(data).filter(([k,v])=>typeof v==='number');return `<div class="note">來源定位：${esc(q.source_locator)} · ${esc(data.task)} · 指標 ${esc(data.metric)}</div><div class="case-chart">${values.map(([name,value])=>`<div class="case-bar"><b>${value}</b><i data-height="${value/Math.max(...values.map(x=>x[1]))*100}"></i><span>${esc(name)}</span></div>`).join('')}</div>`;}
function renderTask(){const task=state.task,q=task.items[state.index].question,r=task.responses[q.id]||{},readonly=task.submission.status!=='in_progress',options=JSON.parse(task.assignment.settings_json);content(head(label(task.assignment.mode),task.assignment.title,options.support_note||'請依題目要求作答；內容會自動儲存到後端。',`<button class="btn" id="back-tasks">返回評量</button>${!readonly?'<button class="btn primary" id="submit-task">繳交整份評量 →</button>':badge(task.submission.status)}`)+`<div class="workbench"><aside class="question-nav"><h3>題目導覽</h3><div class="nav-items">${task.items.map((s,i)=>`<button data-qindex="${i}" class="${state.index===i?'active':''}"><b>${String(i+1).padStart(2,'0')}</b><span><span data-no-i18n>${esc(s.question.title)}</span><br><small>${s.points} 分${task.responses[s.question.id]?' · 已儲存':''}</small></span></button>`).join('')}</div><div class="note">你可以返回前題檢查。繳交後由系統進行批改。</div></aside><section class="panel ${readonly?'read-only':''}" id="answer-panel"><div class="work-head"><div><span class="section-number">CH ${q.skill_id}</span>${badge('',typeNames[q.kind])}${badge('',q.payload.language==='en'?'EN':'中文')}</div><span class="save-state" id="save-state">${readonly?'已繳交':r.text||r.code||r.interaction||r.proposal?'已儲存於後端':'尚未作答'}</span></div><h2 data-no-i18n>${esc(q.title)}</h2><p class="prompt">${esc(q.prompt)}</p>${readingCodeMarkup(q)}${caseReference(q)}<div id="response-fields">${q.kind==='ai_collab_canvas'?canvasMarkup(q,r):q.kind==='case_proposal'?`<div class="case-fields">${q.payload.fields.map((key,i)=>field(key,`<span>${String(i+1).padStart(2,'0')}</span>${proposalLabels[key]}`,`<textarea id="${key}" data-proposal="${key}" placeholder="請具體說明，並連結案例證據。">${esc(r.proposal?.[key]||'')}</textarea>`)).join('')}</div>`:q.kind==='python'?`<div class="note">指定函式：<strong class="mono">${esc(q.tests.function)}</strong> · 純 Python · 不需要 GPU</div><div class="answer-label">你的程式</div><textarea class="code" id="code-answer" spellcheck="false" aria-label="Python 程式碼">${esc(r.code||starter(q))}</textarea><div class="buttons"><button class="btn" id="browser-run" ${!options.allow_browser||readonly?'disabled':''}>▶ 在瀏覽器試跑</button><button class="btn" id="server-run" ${!options.allow_practice||readonly?'disabled':''}>隔離公開測試</button></div><p class="runtime-state" id="runtime-state">瀏覽器試跑是練習結果；正式批改由後端獨立執行。</p><div id="runtime-output"></div><details><summary class="tiny muted">查看公開測試案例</summary><pre>${esc(JSON.stringify(q.tests.public,null,2))}</pre></details>`:interaction(q,r)}${!['case_proposal','ai_collab_canvas'].includes(q.kind)?field('answer-text',q.kind==='python'?'說明你的實作與驗證方式':interaction(q,r)?'說明你的答案與推理':'你的作答',`<textarea id="answer-text" rows="6" placeholder="寫出依據、條件與必要的計算或解釋。">${esc(r.text||'')}</textarea>`):''}</div><div class="work-footer"><button class="btn" id="prev-question" ${state.index===0?'disabled':''}>← 上一題</button><span class="tiny muted">第 ${state.index+1} / ${task.items.length} 題 · ${task.items[state.index].points} 分</span><button class="btn primary" id="next-question" ${state.index===task.items.length-1?'disabled':''}>下一題 →</button></div></section></div>`);if(readonly){$$('#response-fields input,#response-fields textarea,#response-fields select,#response-fields .order-card button,#response-fields [data-cell]').forEach(x=>x.disabled=true);$$('.order-card').forEach(x=>x.draggable=false);}else{bind('#response-fields','input',scheduleSave);bind('#response-fields','change',scheduleSave);setupInteractions();}$$('[data-qindex]').forEach(b=>b.onclick=()=>switchQuestion(Number(b.dataset.qindex)));bind('#prev-question','click',()=>switchQuestion(state.index-1));bind('#next-question','click',()=>switchQuestion(state.index+1));bind('#back-tasks','click',()=>navigate('tasks'));bind('#submit-task','click',()=>{openModal('繳交評量',`<p>這份評量共有 ${task.items.length} 題。繳交後會開始背景批改；尚未作答的部分會記為未展現。</p><p class="note">請先確認所有題目與程式碼。需要修改時可請管理者重新開放。</p>`,'<button class="btn primary" id="confirm-submit">確認繳交</button>');bind('#confirm-submit','click',busy($('#confirm-submit'),async()=>{await saveCurrent();await api(`/api/tasks/${task.assignment.id}/submit`,{});modal.close();state.task=null;toast('已繳交，系統正在安排批改');await navigate('tasks');}));});if(q.kind==='python'&&!readonly){bind('#browser-run','click',()=>browserRun(q));bind('#server-run','click',busy($('#server-run'),async()=>{await saveCurrent();const result=await api(`/api/tasks/${task.assignment.id}/practice`,{question_version_id:q.id,code:$('#code-answer').value});showRuntime(result);}));bind('#code-answer','keydown',e=>{if(e.key==='Tab'){e.preventDefault();const x=e.target,start=x.selectionStart,end=x.selectionEnd;x.value=x.value.slice(0,start)+'    '+x.value.slice(end);x.selectionStart=x.selectionEnd=start+4;scheduleSave();}});}if(q.kind==='ai_collab_canvas')mountCanvas(q,r,readonly);}
function setupInteractions(){let dragging=null;$$('.order-card').forEach(card=>{card.ondragstart=()=>{dragging=card;card.classList.add('dragging');};card.ondragend=()=>{card.classList.remove('dragging');scheduleSave();};card.ondragover=e=>e.preventDefault();card.ondrop=e=>{e.preventDefault();if(dragging&&dragging!==card)card.before(dragging);scheduleSave();};card.querySelector('.order-up').onclick=()=>{if(card.previousElementSibling)card.previousElementSibling.before(card);scheduleSave();};card.querySelector('.order-down').onclick=()=>{if(card.nextElementSibling)card.nextElementSibling.after(card);scheduleSave();};});$$('[data-cell]').forEach(b=>b.onclick=()=>{const on=b.textContent==='0';b.textContent=on?'1':'0';b.classList.toggle('on',on);b.setAttribute('aria-pressed',on);scheduleSave();});}
function responseValue(){const q=state.task.items[state.index].question,result={};if($('#answer-text'))result.text=$('#answer-text').value;if($('#code-answer'))result.code=$('#code-answer').value;if(q.kind==='case_proposal')result.proposal=Object.fromEntries($$('[data-proposal]').map(x=>[x.dataset.proposal,x.value]));const i={};if($('#order-cards'))i.order=$$('[data-card]').map(x=>x.dataset.card);if($('#formula-result'))i.result=$('#formula-result').value;if($$('[data-match]').length)i.mapping=Object.fromEntries($$('[data-match]').map(x=>[x.dataset.match,x.value]));if($$('[data-cell]').length){i.grid=Array.from({length:3},()=>Array(3).fill(0));$$('[data-cell]').forEach(x=>{const[a,b]=x.dataset.cell.split(',').map(Number);i.grid[a][b]=Number(x.textContent);});}if($$('[data-token]').length){i.top_k=$$('[data-token="top_k"]:checked').map(x=>x.value);i.top_p=$$('[data-token="top_p"]:checked').map(x=>x.value);}if($('[name="concept-choice"]:checked'))i.choice=$('[name="concept-choice"]:checked').value;if($$('[data-choice]').length)i.choices=$$('[data-choice]:checked').map(x=>x.value);if(Object.keys(i).length)result.interaction=i;if(q.kind==='ai_collab_canvas')result.canvas=canvasResponse();return result;}
function scheduleSave(){if($('#save-state'))$('#save-state').textContent='尚有未儲存的變更…';clearTimeout(state.saveTimer);state.saveTimer=setTimeout(()=>saveCurrent().catch(e=>{if($('#save-state'))$('#save-state').textContent='儲存失敗，請重試';toast(e.message);}),700);}
async function saveCurrent(){clearTimeout(state.saveTimer);if(!state.task||!$('#response-fields')||state.task.submission.status!=='in_progress')return;const task=state.task;if(task.items[state.index].question.kind==='ai_collab_canvas')await flushCanvas();const vid=task.items[state.index].question.id,response=responseValue();if(JSON.stringify(task.responses[vid])===JSON.stringify(response))return state.savePromise;state.savePromise=state.savePromise.catch(()=>{}).then(async()=>{if($('#save-state'))$('#save-state').textContent='正在儲存…';await api(`/api/tasks/${task.assignment.id}/save`,{question_version_id:vid,response});task.responses[vid]=response;if(state.task===task&&$('#save-state'))$('#save-state').textContent='已儲存於後端';});return state.savePromise;}
async function switchQuestion(i){try{await saveCurrent();state.index=i;renderTask();}catch(e){toast('未完成儲存：'+e.message);}}
function showRuntime(result){$('#runtime-output').innerHTML=`<pre>${esc(result.status==='completed'?`通過 ${result.passed} / ${result.total} 個公開測試\n${JSON.stringify(result.tests,null,2)}\n${result.stdout||''}`:result.error||JSON.stringify(result,null,2))}</pre>`;}
async function browserRun(q){const b=$('#browser-run');b.disabled=true;try{await saveCurrent();$('#runtime-state').textContent='正在載入免費 Python 環境，首次載入可能需要一點時間…';let frame=$('#sandbox-frame');if(!frame){frame=document.createElement('iframe');frame.id='sandbox-frame';frame.className='sandbox-frame';frame.sandbox='allow-scripts';frame.src='/sandbox.html';document.body.append(frame);await new Promise((resolve,reject)=>{frame.onload=resolve;frame.onerror=()=>reject(Error('無法載入練習環境'));});}const id=crypto.randomUUID();const result=await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{window.removeEventListener('message',listener);frame.remove();reject(Error('練習逾時，已停止執行。請檢查迴圈後重試。'));},60000);function listener(e){if(e.source!==frame.contentWindow||e.data?.id!==id)return;clearTimeout(timeout);window.removeEventListener('message',listener);e.data.error?reject(Error(e.data.error)):resolve(e.data.result);}window.addEventListener('message',listener);frame.contentWindow.postMessage({id,code:$('#code-answer').value,tests:q.tests},'*');});showRuntime(result);$('#runtime-state').textContent='瀏覽器練習完成 · 不計入正式成績';}catch(e){toast(e.message);if($('#runtime-state'))$('#runtime-state').textContent=e.message;}finally{b.disabled=false;}}

async function submissions(){const d=await api('/api/admin/submissions');content(head('SUBMISSIONS & GRADING','看分數，也看理由。','AI 批改保留原作答、分項證據與測試結果；實作可另外人工調整。','<button class="btn" id="refresh-submissions">重新整理</button>')+`<section class="panel">${d.submissions.length?`<div class="table-wrap"><table><thead><tr><th>組員 / 評量</th><th>作答狀態</th><th>目前分數</th><th>發布</th><th></th></tr></thead><tbody>${d.submissions.map(s=>`<tr><td><strong data-no-i18n>${esc(s.display_name)}</strong><br><small data-no-i18n>${esc(s.title)}</small></td><td>${badge(s.status)}</td><td>${s.result?.complete?`${s.result.score} / ${s.result.max_score}`:s.result?'待補充分項':'等待分析'}</td><td>${badge(s.published?'approved':'draft',s.published?'已發布':'尚未發布')}</td><td><button class="btn small" data-submission="${s.id}">查看 / 調分</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">尚未收到組員作答。</div>'}</section>`);bind('#refresh-submissions','click',submissions);$$('[data-submission]').forEach(b=>b.onclick=()=>reviewSubmission(b.dataset.submission));}
function reportMarkup(report,editable=false){return `<div class="report-hero"><div><div class="eyebrow">UNDERSTANDING & NEXT STEP</div><h2>${editable?'批改結果':'本次評量表現'}</h2><p>${esc(report.source)}${report.model?` · ${esc(report.model)} / ${esc(report.reasoning||'medium')}`:''} · ${report.complete?'分項評分完整':'部分分項待處理'}</p></div><div class="report-score">${report.complete?report.score:'—'} <small>/ ${report.max_score}</small></div></div>${report.review_note?`<div class="note">人工評語：${esc(report.review_note)}</div>`:''}${report.items.map(item=>`<section class="panel"><div class="panel-head"><div><span class="section-number">${esc(item.skill_id)}</span><strong data-no-i18n>${esc(item.title)}</strong></div><small>${item.score??'待評'} / ${item.assigned_points} 分</small></div>${item.criteria.map(r=>`<div class="criterion"><div class="criterion-top"><strong>${esc(r.name)}</strong>${editable?`<select data-level="${item.question_version_id}:${r.id}" aria-label="${esc(r.name)} 等級"><option value="">待評</option>${[0,1,2,3].map(v=>`<option value="${v}" ${r.level===v?'selected':''}>${v} 級</option>`).join('')}</select>`:badge(r.level>=2?'approved':'draft',r.level===null?'待評':`${r.level} / 3 級`)}</div><p>${contentText(r.reason)}</p>${r.quote?`<blockquote>${esc(r.quote)}</blockquote>`:''}<p><strong>下一步：</strong>${contentText(r.feedback)}</p><small>${esc({'ai':'AI 評分','rule':'固定規則','sandbox_tests':'隔離測試','human_review':'人工覆核','pending':'尚未完成'}[r.method]||r.method)} · ${r.points===null?'待評':r.points.toFixed(2)} / ${r.max_points.toFixed(2)} 分</small></div>`).join('')}${item.test_result?`<details><summary class="tiny muted">實作執行結果</summary><pre>${esc(JSON.stringify(item.test_result,null,2))}</pre></details>`:''}</section>`).join('')}<p class="note">這份報告描述本次作答。分數與支持需求不代表固定人格或學習動機；相同題目的修訂不會增加獨立評量次數。</p>`;}
async function reviewSubmission(id){try{const d=await api(`/api/admin/submissions/${id}`);content(head('REVIEW WORKSPACE',d.assignment.title,'保留 AI 原始結果，再依需要修改分項、加入評語或重新分析。','<button class="btn" id="canvas-review-history">檢視白板與 AI 過程</button><button class="btn" id="back-submissions">返回列表</button><button class="btn" id="retry-analysis">重新 AI 批改</button><button class="btn" id="reopen-submission">重新開放作答</button>')+`<div class="review-grid"><div><section class="panel"><h2>原始作答與參考內容</h2>${d.private_items.map(item=>{const r=d.responses[item.question.id]||{};return `<details><summary class="question-title">${esc(item.question.title)}</summary><p class="prompt">${esc(item.question.prompt)}</p>${readingCodeMarkup(item.question)}<h3>組員作答</h3><pre>${esc(JSON.stringify(r,null,2))}</pre><h3>答案要點</h3><ul class="rubric-list">${item.question.answer.expected_elements.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${guideMarkup(item.question,false)}</details>`;}).join('')}</section>${d.review_history.length?`<section class="panel"><h3>人工調分紀錄</h3>${d.review_history.map(h=>`<p class="tiny muted">版本 ${h.revision} · ${fmt(h.created_at+'Z')}</p>`).join('')}</section>`:''}</div><div>${d.original_ai_result&&d.review_history.length?`<section class="panel"><details><summary>檢視原始 AI 批改（調分前）</summary>${reportMarkup(d.original_ai_result)}</details></section>`:''}${d.result?reportMarkup(d.result,true)+`<section class="panel">${field('review-note','實作／人工評語','<textarea id="review-note" rows="4" placeholder="說明調分或實作檢查結果。"></textarea>')}<label class="check-label"><input id="publish-review" type="checkbox" checked>儲存後發布這份成績與回饋</label><button class="btn primary" id="save-review">儲存人工覆核</button></section>`:'<section class="panel"><div class="empty">分析尚未完成。你可以稍後重新整理，或查看工作區的分析狀態。</div></section>'}</div></div>`);bind('#canvas-review-history','click',()=>canvasReviewHistory(id).catch(e=>toast(e.message)));bind('#back-submissions','click',()=>navigate('submissions'));bind('#retry-analysis','click',busy($('#retry-analysis'),async()=>{await api(`/api/admin/submissions/${id}/retry`,{});toast('已加入重新批改佇列');await navigate('submissions');}));bind('#reopen-submission','click',busy($('#reopen-submission'),async()=>{await api(`/api/admin/submissions/${id}/reopen`,{});toast('已建立修訂作答，組員可以繼續修改');await navigate('submissions');}));bind('#save-review','click',busy($('#save-review'),async()=>{const levels=Object.fromEntries($$('[data-level]').map(x=>[x.dataset.level,x.value===''?null:Number(x.value)]));await api(`/api/admin/submissions/${id}/review`,{levels,note:$('#review-note').value,publish:$('#publish-review').checked});toast('人工覆核已儲存');await navigate('submissions');}));}catch(e){toast(e.message);}}
async function reports(){const d=await api('/api/reports');content(head('MY FEEDBACK','理解的證據，下一步的方向。','已發布的分項分數與回饋，會保留具體理由和作答證據。')+(d.reports.length?d.reports.map(r=>`<article class="task-card"><div><div class="eyebrow">PUBLISHED REPORT</div><h3 data-no-i18n>${esc(r.title)}</h3><p>${esc(r.report.source)}</p></div><div class="buttons"><strong>${r.report.score} / ${r.report.max_score}</strong><button class="btn" data-report="${r.id}">查看報告 →</button></div></article>`).join(''):'<section class="panel"><div class="empty">尚無已發布的報告。完成作答後，AI 或管理者會發布回饋。</div></section>'));$$('[data-report]').forEach(b=>b.onclick=()=>{const r=d.reports.find(x=>x.id===b.dataset.report);content(head('MY FEEDBACK',r.title,'對照作答證據，檢查你的解釋與改善方案。','<button class="btn" id="back-reports">返回報告</button>')+reportMarkup(r.report));bind('#back-reports','click',reports);});}
async function overview(){const d=await api('/api/admin/overview');content(head('EVIDENCE PROFILE','看見優勢，也定位支持需求。','依已發布、可比的作答彙整。練習與正式檢測分開，相同題目不重複計入。')+`<section class="panel"><div class="panel-head"><h2>技能達標證據</h2><small>達標 = 本題所有適用分項至少 2 級</small></div>${d.overview.length?`<table><thead><tr><th>組員</th><th>小節</th><th>模式 / 條件</th><th>達標 / 可比機會</th><th>證據比例</th></tr></thead><tbody>${d.overview.map(r=>`<tr><td>${esc(r.learner)}</td><td class="mono">${r.skill}</td><td>${badge(r.mode)}<br><small>${esc(typeNames[r.kind]||r.kind)} · ${esc(r.difficulty)}<br>試跑 ${r.allow_practice?"開":"關"} · 本機練習 ${r.allow_browser?"開":"關"}<br>${esc(r.support)}</small></td><td>${r.met} / ${r.count}${r.unknown?` · ${r.unknown} 未評`:''}</td><td><div class="meter"><span data-percent="${r.count?r.met/r.count*100:0}"></span></div><small>${r.count<3?'證據較少，需更多獨立案例':'僅描述可比作答'}</small></td></tr>`).join('')}</tbody></table>`:'<div class="empty">目前沒有可彙整的已發布作答。</div>'}</section><section class="panel"><h2>補強題建議</h2><p class="tiny muted">建議依技能缺口篩選已核准題目，仍由你選擇搭配與分配。</p>${d.recommendations.length?d.recommendations.map(r=>`<div class="list-row"><div><h3>${esc(r.display_name)} · ${esc(r.title)}</h3><p>${esc(JSON.parse(r.reason_json).reason)}</p></div><button class="btn small recommendation-compose">前往組卷</button></div>`).join(''):'<div class="empty">有可定位的未達標分項後，才會產生補強建議。</div>'}</section>`);$$('.recommendation-compose').forEach(b=>b.onclick=()=>navigate('assignments'));}
async function settings(){const admin=state.session.user.role==='admin';let d=admin?await api('/api/admin/settings'):null;content(head('WORKSPACE SETTINGS',admin?'設定批改環境。':'帳戶設定。',admin?'使用本機免費模型，並確認隔離程式執行環境。':'更改密碼後，請重新登入。')+`<div class="columns">${admin?`<section class="panel"><h2>AI 批改</h2><p class="tiny muted">從本機 Ollama 選擇模型。AI 無法完成有效評分时，保留待處理狀態。</p>${field('ai-model','模型',`<input id="ai-model" list="model-list" value="${esc(d.ai.model)}"><datalist id="model-list">${d.models.map(m=>`<option value="${esc(m)}"></option>`).join('')}</datalist>`)}${field('ai-reasoning','推理程度（gpt-oss）',`<select id="ai-reasoning">${['low','medium','high'].map(v=>`<option value="${v}" ${(d.ai.reasoning||'medium')===v?'selected':''}>${{low:'低',medium:'中',high:'高'}[v]}</option>`).join('')}</select>`,'較高推理程度通常需要較長批改時間。')}<label class="check-label"><input type="checkbox" id="ai-enabled" ${d.ai.enabled?'checked':''}>啟用 AI 分項批改</label><div class="note ${d.models.includes(d.ai.model)?'':'warn'}">${d.models.includes(d.ai.model)?'指定模型已就緒':'指定模型尚未下載完成或無法使用'}：${esc(d.ai.model)}<details><summary>檢視本機已安裝模型</summary>${esc(d.models.join('、')||'Ollama 尚未連線')}</details></div><div class="buttons"><button class="btn primary" id="save-ai">儲存 AI 設定</button><button class="btn" id="refresh-settings">重新檢查</button></div></section><section class="panel"><h2>Python 執行環境</h2><div class="list-row"><div><h3>瀏覽器練習</h3><p>免費 Pyodide · CPU 執行 · 無需 GPU</p></div>${badge('approved','可於實作題試跑')}</div><div class="list-row"><div><h3>正式隔離測試</h3><p>${esc(d.runner.available?d.runner.image:d.runner.reason)}</p></div>${badge(d.runner.available?'approved':'draft',d.runner.available?'已就緒':'待啟動')}</div><p class="note">正式成績不信任瀏覽器回傳結果。後端使用獨立 Linux 環境重跑，實作分數可人工調整。</p></section>`:''}<section class="panel"><h2>更改登入密碼</h2>${field('old-password','原密碼',input('old-password','password','','autocomplete="current-password"'))}${field('new-password','新密碼',input('new-password','password','','minlength="10" autocomplete="new-password"'))}<button class="btn" id="change-password">更新密碼</button></section>${admin?'<section class="panel"><h2>操作紀錄</h2><p class="tiny muted">題目核准、分配與人工調分保留可追溯紀錄。</p><button class="btn" id="view-audit">查看最近操作</button></section>':''}</div>`);if(admin){await collabSettingsPanel();bind('#save-ai','click',busy($('#save-ai'),async()=>{await api('/api/admin/settings',{model:$('#ai-model').value,enabled:$('#ai-enabled').checked,reasoning:$('#ai-reasoning').value});toast('AI 設定已更新');}));bind('#refresh-settings','click',settings);bind('#view-audit','click',async()=>{try{const a=await api('/api/admin/audit');openModal('最近操作紀錄',`<pre>${esc(JSON.stringify(a.events,null,2))}</pre>`);}catch(e){toast(e.message);}});}bind('#change-password','click',busy($('#change-password'),async()=>{await api('/api/password',{old_password:$('#old-password').value,password:$('#new-password').value});toast('密碼已更新，請重新登入');await boot();}));}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
window.addEventListener('beforeunload',e=>{if($('#save-state')?.textContent.includes('未儲存')){e.preventDefault();e.returnValue='';}});
document.addEventListener('DOMContentLoaded',boot,{once:true});
